import path from "node:path";
import { fileURLToPath } from "node:url";
import { normalizePath, type Plugin } from "vite";

/**
 * Serves `base44:private-data-sources/<type>` to TanStack server code, so it
 * reaches a workspace private data source with the SAME import a backend
 * function uses:
 *
 *   import { sqlserver } from "base44:private-data-sources/sqlserver";
 *
 * The modules are this package's own copy of the backend-function adapters
 * (`@base44/functions-compiler`, forked at base44/cli ac98feb), reading the worker's bindings and manifest off
 * `env` from `cloudflare:workers`. Each specifier resolves to the compiled file
 * so Vite bundles it like any source module.
 *
 * The bindings exist only on the deployed worker: in the editor's dev preview a
 * lookup throws, saying the source is available on the published app.
 */

const NAMESPACE = "base44:private-data-sources";
const PREFIX = `${NAMESPACE}/`;
const SOURCE_TYPES = new Set([
  "elasticsearch",
  "http",
  "mariadb",
  "mongodb",
  "mysql",
  "oracle",
  "postgres",
  "redis",
  "sqlserver",
]);
const IMPORTER_QUERY = "?importer=";

const MODULES_DIR = path.join(path.dirname(fileURLToPath(import.meta.url)), "private-data-sources");

function failureReason(specifier: string, environment: string | undefined): string | null {
  const sourceType = specifier.startsWith(PREFIX) ? specifier.slice(PREFIX.length) : "";
  if (!SOURCE_TYPES.has(sourceType)) {
    return `"${specifier}" is not a private data source type. Use one of: ${[...SOURCE_TYPES].map((t) => PREFIX + t).join(", ")}.`;
  }
  // The source carries credentials, so it must never reach the browser bundle.
  if (environment === "client") {
    return `"${specifier}" is server-only. Move this import into a server function or server route.`;
  }
  return null;
}

export function privateDataSourcesPlugin(): Plugin {
  return {
    name: "base44-private-data-sources",
    // Ahead of Vite's own resolution so the bare scheme is never read as a URL.
    enforce: "pre",

    // Like base44-runtime: errors are raised in `load`, never `resolveId`, so the
    // dep scan of not-yet-stripped server code in the client environment survives.
    resolveId(id, importer) {
      if (id !== NAMESPACE && !id.startsWith(PREFIX)) return null;
      if (!failureReason(id, this.environment?.name)) {
        return normalizePath(path.join(MODULES_DIR, `${id.slice(PREFIX.length)}.js`));
      }
      const virtual = `\0${id}`;
      if (!importer) return virtual;
      return `${virtual}${IMPORTER_QUERY}${Buffer.from(importer.split("?")[0]!).toString("base64url")}`;
    },

    load(id) {
      if (!id.startsWith("\0")) return null;
      const [specifier = "", importer] = id.slice(1).split(IMPORTER_QUERY);
      if (specifier !== NAMESPACE && !specifier.startsWith(PREFIX)) return null;
      const from = importer ? ` Imported from ${Buffer.from(importer, "base64url").toString()}.` : "";
      const reason = failureReason(specifier, this.environment?.name);
      this.error(`${reason ?? `"${specifier}" cannot be loaded here.`}${from}`);
    },
  };
}
